begin;
alter table public.institutional_section_variants add column if not exists family_key text;
alter table public.institutional_templates add column if not exists family_key text;
create index if not exists institutional_section_variants_family_idx on public.institutional_section_variants(family_key, section_type, status, visibility);
create index if not exists institutional_templates_family_idx on public.institutional_templates(family_key, status, visibility);
-- Retire every previous native design from discovery. Existing sites keep rendering
-- because their referenced versions are preserved; only the creation catalog changes.
update public.institutional_section_variants set status='draft', visibility='private', family_key='legacy-retired' where is_system=true;
update public.institutional_templates set status='draft', visibility='private', family_key='legacy-retired' where is_system=true;
on conflict (id) do update set name=excluded.name, description=excluded.description, family_key=excluded.family_key, is_system=true, visibility='public', status='published';
on conflict (id) do update set status='published', layout=excluded.layout;
on conflict (id) do update set name=excluded.name, description=excluded.description, category=excluded.category, family_key=excluded.family_key, is_system=true, visibility='public', status='published', definition=excluded.definition;
commit;
